-- 1. Fármacos novos
-- ----------------------------------------------------------------
INSERT INTO public.drugs (slug, name_pt, name_en, class_pt, class_en, aliases, status, sort_order) VALUES
  ('nistatina', 'Nistatina', 'Nystatin', 'Antifúngico poliénico (uso oral)', 'Polyene antifungal (oral use)', ARRAY['Nystan', 'Micostatin', 'nystatin'], 'published', 139),
  ('famotidina', 'Famotidina', 'Famotidine', 'Antiácidos e anti-ulcerosos — antagonista dos recetores H2', 'Antacids and anti-ulcer agents — histamine H2-receptor antagonist', ARRAY['Pepcid', 'famotidine'], 'published', 140),
  ('sucralfato', 'Sucralfato', 'Sucralfate', 'Citoprotetor da mucosa gástrica (anti-ulceroso)', 'Gastric mucosal cytoprotectant (anti-ulcer)', ARRAY['Antepsin', 'Carafate', 'sucralfate'], 'published', 141),
  ('metoclopramida', 'Metoclopramida', 'Metoclopramide', 'Procinético / antiemético (antagonista dopaminérgico)', 'Prokinetic / antiemetic (dopamine antagonist)', ARRAY['Primperan', 'Maxolon', 'metoclopramide'], 'published', 142),
  ('domperidona', 'Domperidona', 'Domperidone', 'Procinético / antiemético (antagonista dopaminérgico periférico)', 'Prokinetic / antiemetic (peripheral dopamine antagonist)', ARRAY['Motilium', 'domperidone'], 'published', 143),
  ('loperamida', 'Loperamida', 'Loperamide', 'Antidiarreico (agonista opioide de ação periférica)', 'Antidiarrhoeal (peripheral opioid agonist)', ARRAY['Imodium', 'loperamide'], 'published', 144),
  ('ondansetron', 'Ondansetrom', 'Ondansetron', 'Antiemético (antagonista dos recetores 5-HT3)', 'Antiemetic (5-HT3 receptor antagonist)', ARRAY['Zofran', 'Zofren', 'ondansetron'], 'published', 145),
  ('butilbrometo_hioscina', 'Butilbrometo de hioscina', 'Hyoscine butylbromide', 'Antiespasmódico (anticolinérgico)', 'Antispasmodic (antimuscarinic)', ARRAY['Buscopan', 'butilbrometo de escopolamina', 'hyoscine butylbromide', 'butylscopolamine'], 'published', 146),
  ('orlistat', 'Orlistato', 'Orlistat', 'Inibidor das lipases gastrintestinais (anti-obesidade)', 'Gastrointestinal lipase inhibitor (anti-obesity)', ARRAY['Xenical', 'Alli', 'orlistate'], 'published', 147),
  ('mesalazina', 'Mesalazina', 'Mesalazine', 'Anti-inflamatório intestinal (derivado do ácido 5-aminossalicílico)', 'Intestinal anti-inflammatory (5-aminosalicylic acid derivative)', ARRAY['Mesalamine', 'Asacol', 'Pentasa', 'mesalazine'], 'published', 148),
  ('sulfassalazina', 'Sulfassalazina', 'Sulfasalazine', 'Anti-inflamatório intestinal (pró-fármaco de 5-ASA + sulfapiridina)', 'Intestinal anti-inflammatory (prodrug of 5-ASA + sulfapyridine)', ARRAY['Salazopyrin', 'Azulfidine', 'sulfasalazine'], 'published', 149),
  ('acido_ursodesoxicolico', 'Ácido ursodesoxicólico', 'Ursodeoxycholic acid', 'Ácido biliar (colerético / litolítico)', 'Bile acid (choleretic / litholytic)', ARRAY['Ursodiol', 'Urso', 'ursodeoxycholic acid', 'ácido ursodeoxicólico'], 'published', 150);

-- ----------------------------------------------------------------
-- 2. Fármaco-fármaco (drug_interactions)
-- ----------------------------------------------------------------
INSERT INTO public.drug_interactions
  (drug_a_id, drug_b_id, severity, summary_pt, summary_en, mechanism_pt, mechanism_en,
   management_pt, management_en, monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
   source_pt, source_en, status)
SELECT LEAST(a.id, b.id), GREATEST(a.id, b.id), v.severity, v.summary_pt, v.summary_en,
       v.mechanism_pt, v.mechanism_en, v.management_pt, v.management_en,
       v.monitoring_pt, v.monitoring_en, v.red_flags_pt, v.red_flags_en,
       v.source_pt, v.source_en, 'published'
FROM (VALUES
  ('domperidona', 'claritromicina', 'critical', 'A associação de domperidona com claritromicina está contraindicada: a claritromicina inibe o CYP3A4 e aumenta as concentrações de domperidona, com risco elevado de prolongamento do intervalo QT e torsade de pointes.', 'Combining domperidone with clarithromycin is contraindicated: clarithromycin inhibits CYP3A4 and raises domperidone concentrations, with a high risk of QT-interval prolongation and torsade de pointes.', 'A claritromicina é um inibidor potente do CYP3A4, principal via de metabolização da domperidona; ambas as substâncias prolongam o QT.', 'Clarithromycin is a potent CYP3A4 inhibitor, the main metabolic pathway of domperidone; both substances prolong the QT interval.', 'Evitar a associação; escolher um macrólido alternativo ou um procinético/antiemético sem risco QT.', 'Avoid the combination; choose an alternative macrolide or a prokinetic/antiemetic without QT risk.', 'Vigiar ECG (intervalo QT) e sintomas de arritmia (palpitações, síncope).', 'Monitor ECG (QT interval) and arrhythmia symptoms (palpitations, syncope).', 'Torsade de pointes, morte súbita.', 'Torsade de pointes, sudden death.', 'DailyMed (FDA) — rótulo aprovado Domperidona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=cdb0c9b9-388c-4a06-9fe9-bb4e52278a4e ; rótulo aprovado Claritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Domperidone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=cdb0c9b9-388c-4a06-9fe9-bb4e52278a4e ; approved Clarithromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('domperidona', 'ciprofloxacina', 'moderate', 'A ciprofloxacina pode aumentar a exposição à domperidona e somar efeitos no intervalo QT.', 'Ciprofloxacin may increase domperidone exposure and add QT-interval effects.', 'A ciprofloxacina inibe parcialmente o CYP3A4 e ambas prolongam o QT.', 'Ciprofloxacin partially inhibits CYP3A4 and both prolong the QT.', 'Usar com precaução; considerar alternativa se houver fatores de risco QT.', 'Use with caution; consider an alternative if QT risk factors are present.', 'Vigiar ECG em doentes com fatores de risco (hipocaliemia, bradicardia, outros fármacos QT).', 'Monitor ECG in patients with risk factors (hypokalaemia, bradycardia, other QT drugs).', 'Arritmias ventriculares, torsade de pointes (raro).', 'Ventricular arrhythmias, torsade de pointes (rare).', 'DailyMed (FDA) — rótulo aprovado Domperidona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=cdb0c9b9-388c-4a06-9fe9-bb4e52278a4e ; rótulo aprovado Ciprofloxacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Domperidone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=cdb0c9b9-388c-4a06-9fe9-bb4e52278a4e ; approved Ciprofloxacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('ondansetron', 'tramadol', 'moderate', 'A associação de ondansetrom com tramadol aumenta o risco de síndrome serotoninérgico.', 'Combining ondansetron with tramadol raises the risk of serotonin syndrome.', 'O tramadol é serotoninérgico e o ondansetrom, embora antagonista 5-HT3, pode contribuir para excesso serotoninérgico em doentes suscetíveis.', 'Tramadol is serotonergic and ondansetron, although a 5-HT3 antagonist, may contribute to serotonergic excess in susceptible patients.', 'Vigiar sintomas serotoninérgicos; usar com precaução em doentes polimedicados.', 'Monitor serotonergic symptoms; use with caution in polypharmacy patients.', 'Vigiar agitação, tremor, hipertermia, mioclonias e diarreia.', 'Monitor agitation, tremor, hyperthermia, myoclonus and diarrhoea.', 'Síndrome serotoninérgico (hipertermia, rigidez, confusão).', 'Serotonin syndrome (hyperthermia, rigidity, confusion).', 'DailyMed (FDA) — rótulo aprovado Ondansetrom: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=41366a20-0727-0446-e063-6294a90a957f ; rótulo aprovado Tramadol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Ondansetron label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=41366a20-0727-0446-e063-6294a90a957f ; approved Tramadol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('metoclopramida', 'levotiroxina', 'moderate', 'A metoclopramida aumenta a motilidade gástrica e pode reduzir a absorção da levotiroxina, diminuindo o seu efeito.', 'Metoclopramide increases gastric motility and may reduce levothyroxine absorption, decreasing its effect.', 'A aceleração do esvaziamento gástrico encurta o tempo de contacto da levotiroxina com a mucosa absortiva.', 'Accelerated gastric emptying shortens levothyroxine contact time with the absorptive mucosa.', 'Separar as tomas e monitorizar a TSH ao iniciar ou suspender a metoclopramida.', 'Separate administration times and monitor TSH when starting or stopping metoclopramide.', 'Monitorizar TSH e sintomas de hipotiroidismo (fadiga, ganho de peso).', 'Monitor TSH and hypothyroidism symptoms (fatigue, weight gain).', 'Hipotiroidismo descompensado.', 'Decompensated hypothyroidism.', 'DailyMed (FDA) — rótulo aprovado Metoclopramida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d31d815-50fa-4e78-8ebd-affc2514ce78 ; rótulo aprovado Levotiroxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Metoclopramide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d31d815-50fa-4e78-8ebd-affc2514ce78 ; approved Levothyroxine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('metoclopramida', 'digoxina', 'moderate', 'A metoclopramida pode reduzir a absorção da digoxina e, em alguns doentes, atrasar o seu efeito terapêutico.', 'Metoclopramide may reduce digoxin absorption and, in some patients, delay its therapeutic effect.', 'O aumento do trânsito intestinal pela metoclopramida reduz o tempo de absorção da digoxina.', 'Metoclopramide-induced faster intestinal transit reduces digoxin absorption time.', 'Monitorizar a resposta clínica e considerar dose ajustada ou esquema alternativo.', 'Monitor clinical response and consider dose adjustment or an alternative schedule.', 'Vigiar a resposta antiarrítmica/antifibrilatória e sintomas de insuficiência cardíaca.', 'Monitor the antiarrhythmic/rate-control response and heart failure symptoms.', 'Perda de controlo do ritmo/da insuficiência cardíaca.', 'Loss of rhythm/heart failure control.', 'DailyMed (FDA) — rótulo aprovado Metoclopramida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d31d815-50fa-4e78-8ebd-affc2514ce78 ; rótulo aprovado Digoxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Metoclopramide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5d31d815-50fa-4e78-8ebd-affc2514ce78 ; approved Digoxin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('loperamida', 'claritromicina', 'moderate', 'A claritromicina pode aumentar as concentrações de loperamida, potenciando efeitos depressores do SNC e cardíacos.', 'Clarithromycin may raise loperamide concentrations, potentiating CNS-depressant and cardiac effects.', 'A inibição do CYP3A4 pela claritromicina aumenta a exposição à loperamida.', 'CYP3A4 inhibition by clarithromycin increases loperamide exposure.', 'Usar a menor dose eficaz e vigiar efeitos adversos; evitar doses altas.', 'Use the lowest effective dose and monitor adverse effects; avoid high doses.', 'Vigiar sonolência, obstipação, palpitações e alterações do ritmo.', 'Monitor drowsiness, constipation, palpitations and rhythm changes.', 'Toxicidade por loperamida (SNC, QT).', 'Loperamide toxicity (CNS, QT).', 'DailyMed (FDA) — rótulo aprovado Loperamida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=568064c9-139d-7233-e063-6294a90a10d4 ; rótulo aprovado Claritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Loperamide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=568064c9-139d-7233-e063-6294a90a10d4 ; approved Clarithromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('sucralfato', 'ciprofloxacina', 'moderate', 'O sucralfato reduz significativamente a absorção oral da ciprofloxacina quando administrado em simultâneo.', 'Sucralfate significantly reduces oral ciprofloxacin absorption when given at the same time.', 'O sucralfato forma complexos de quelação com as fluoroquinolonas no trato gastrointestinal.', 'Sucralfate chelates fluoroquinolones in the gastrointestinal tract.', 'Administrar a ciprofloxacina 2 horas antes ou 6 horas após o sucralfato.', 'Give ciprofloxacin 2 hours before or 6 hours after sucralfate.', 'Vigiar a resposta clínica à antibioterapia.', 'Monitor the clinical response to antibiotic therapy.', 'Falha terapêutica da ciprofloxacina.', 'Ciprofloxacin therapeutic failure.', 'DailyMed (FDA) — rótulo aprovado Sucralfato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; rótulo aprovado Ciprofloxacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Sucralfate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; approved Ciprofloxacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('sucralfato', 'digoxina', 'moderate', 'O sucralfato pode reduzir a absorção da digoxina, diminuindo o seu efeito.', 'Sucralfate may reduce digoxin absorption, decreasing its effect.', 'A ligação do sucralfato à digoxina no trato gastrointestinal reduz a sua biodisponibilidade.', 'Sucralfate binding to digoxin in the gut reduces its bioavailability.', 'Separar as tomas (2 horas) e monitorizar níveis/resposta.', 'Separate administration times (2 hours) and monitor levels/response.', 'Vigiar a frequência cardíaca e sintomas de insuficiência cardíaca.', 'Monitor heart rate and heart failure symptoms.', 'Perda de controlo do ritmo/da insuficiência cardíaca.', 'Loss of rhythm/heart failure control.', 'DailyMed (FDA) — rótulo aprovado Sucralfato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; rótulo aprovado Digoxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Sucralfate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; approved Digoxin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('sucralfato', 'levotiroxina', 'moderate', 'O sucralfato reduz a absorção da levotiroxina, comprometendo o controlo do hipotiroidismo.', 'Sucralfate reduces levothyroxine absorption, compromising hypothyroidism control.', 'Quelação/adsorção da levotiroxina pelo sucralfato no trato gastrointestinal.', 'Chelation/adsorption of levothyroxine by sucralfate in the gut.', 'Separar as tomas (4 horas) e monitorizar TSH.', 'Separate administration times (4 hours) and monitor TSH.', 'Monitorizar TSH e sintomas de hipotiroidismo.', 'Monitor TSH and hypothyroidism symptoms.', 'Hipotiroidismo descompensado.', 'Decompensated hypothyroidism.', 'DailyMed (FDA) — rótulo aprovado Sucralfato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; rótulo aprovado Levotiroxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Sucralfate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; approved Levothyroxine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('sucralfato', 'antiacidos', 'moderate', 'Os antiácidos podem reduzir o efeito protetor do sucralfato quando tomados em simultâneo.', 'Antacids may reduce the protective effect of sucralfate when taken together.', 'Os antiácidos alteram o pH gástrico e podem interferir com a polimerização do sucralfato.', 'Antacids change gastric pH and may interfere with sucralfate polymerisation.', 'Separar as tomas do sucralfato e dos antiácidos (30–60 minutos).', 'Separate sucralfate and antacid administration (30–60 minutes).', 'Vigiar a resposta sintomática (dor epigástrica, pirose).', 'Monitor symptomatic response (epigastric pain, heartburn).', 'Recidiva de sintomas ulcerosos.', 'Recurrence of ulcer symptoms.', 'DailyMed (FDA) — rótulo aprovado Sucralfato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; rótulo aprovado Antiácidos: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Sucralfate label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1e781cc0-24ec-4028-8262-dcef9873ea1f ; approved Antacids label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('orlistat', 'warfarina', 'moderate', 'O orlistato pode reduzir a absorção da vitamina K e alterar o INR em doentes a tomar varfarina.', 'Orlistat may reduce vitamin K absorption and alter the INR in patients taking warfarin.', 'A diminuição da absorção de vitamina K lipossolúvel interfere com a síntese dos fatores de coagulação dependentes da vitamina K.', 'Reduced fat-soluble vitamin K absorption interferes with synthesis of vitamin K-dependent clotting factors.', 'Monitorizar o INR com maior frequência ao iniciar, ajustar ou suspender o orlistato.', 'Monitor the INR more frequently when starting, adjusting or stopping orlistat.', 'Vigiar sinais de hemorragia e o INR.', 'Monitor bleeding signs and INR.', 'Hemorragia ou eventos trombóticos por INR instável.', 'Bleeding or thrombotic events from unstable INR.', 'DailyMed (FDA) — rótulo aprovado Orlistato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a2d3bd73-f3af-4ea5-a57c-66b0004cfe4f ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Orlistat label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a2d3bd73-f3af-4ea5-a57c-66b0004cfe4f ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('orlistat', 'levotiroxina', 'moderate', 'O orlistato reduz a absorção da levotiroxina, podendo comprometer o controlo do hipotiroidismo.', 'Orlistat reduces levothyroxine absorption and may compromise hypothyroidism control.', 'Interferência com a absorção de substâncias lipossolúveis / janela de absorção da levotiroxina.', 'Interference with fat-soluble absorption / levothyroxine absorption window.', 'Separar as tomas (4 horas) e monitorizar TSH.', 'Separate administration times (4 hours) and monitor TSH.', 'Monitorizar TSH e sintomas de hipotiroidismo.', 'Monitor TSH and hypothyroidism symptoms.', 'Hipotiroidismo descompensado.', 'Decompensated hypothyroidism.', 'DailyMed (FDA) — rótulo aprovado Orlistato: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a2d3bd73-f3af-4ea5-a57c-66b0004cfe4f ; rótulo aprovado Levotiroxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Orlistat label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a2d3bd73-f3af-4ea5-a57c-66b0004cfe4f ; approved Levothyroxine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('mesalazina', 'azatioprina', 'moderate', 'A mesalazina pode potenciar a mielossupressão da azatioprina (inibição da TPMT).', 'Mesalazine may potentiate azathioprine myelosuppression (TPMT inhibition).', 'A mesalazina inibe a tiopurina metiltransferase (TPMT), aumentando os níveis de 6-tioguanina ativa.', 'Mesalazine inhibits thiopurine methyltransferase (TPMT), raising active 6-thioguanine levels.', 'Monitorizar o hemograma com regularidade; vigiar sinais de infeção e equimoses.', 'Monitor the blood count regularly; watch for infection and bruising.', 'Hemograma completo periódico, sobretudo nas primeiras semanas.', 'Periodic full blood count, especially in the first weeks.', 'Leucopenia, trombocitopenia, infeções graves.', 'Leucopenia, thrombocytopenia, serious infections.', 'DailyMed (FDA) — rótulo aprovado Mesalazina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=47b5d1ee-b439-4ccb-9b01-c0875ccd748a ; rótulo aprovado Azatioprina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Mesalazine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=47b5d1ee-b439-4ccb-9b01-c0875ccd748a ; approved Azathioprine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('sulfassalazina', 'acido_folico', 'moderate', 'A sulfassalazina pode reduzir a absorção do ácido fólico e o seu efeito, sobretudo em uso prolongado.', 'Sulfasalazine may reduce folic acid absorption and its effect, especially with long-term use.', 'Inibição do transportador de folato intestinal pela sulfapiridina (metabolito da sulfassalazina).', 'Inhibition of the intestinal folate transporter by sulfapyridine (a sulfasalazine metabolite).', 'Considerar suplementação de ácido fólico em doentes em tratamento prolongado, sobretudo se anemia ou gravidez.', 'Consider folic acid supplementation in patients on long-term therapy, especially with anaemia or pregnancy.', 'Vigiar hemograma e sinais de anemia megaloblástica.', 'Monitor blood count and signs of megaloblastic anaemia.', 'Anemia megaloblástica.', 'Megaloblastic anaemia.', 'DailyMed (FDA) — rótulo aprovado Sulfassalazina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d967092f-9685-446b-b7b8-17821e29417b ; rótulo aprovado Ácido fólico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0baa10dd-6d1d-4946-8236-566451132da3 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Sulfasalazine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d967092f-9685-446b-b7b8-17821e29417b ; approved Folic acid label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0baa10dd-6d1d-4946-8236-566451132da3 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('sulfassalazina', 'azatioprina', 'moderate', 'A sulfassalazina, como a mesalazina, pode inibir a TPMT e aumentar a toxicidade da azatioprina.', 'Sulfasalazine, like mesalazine, may inhibit TPMT and increase azathioprine toxicity.', 'Inibição da TPMT pela sulfassalazina com aumento dos metabolitos ativos da azatioprina.', 'TPMT inhibition by sulfasalazine with increased active azathioprine metabolites.', 'Monitorizar hemograma e dose de azatioprina.', 'Monitor blood count and azathioprine dose.', 'Hemograma periódico.', 'Periodic blood count.', 'Mielossupressão.', 'Myelosuppression.', 'DailyMed (FDA) — rótulo aprovado Sulfassalazina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d967092f-9685-446b-b7b8-17821e29417b ; rótulo aprovado Azatioprina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Sulfasalazine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d967092f-9685-446b-b7b8-17821e29417b ; approved Azathioprine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5116b22b-1460-5535-e063-6394a90acbe5 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('omeprazol', 'warfarina', 'moderate', 'O omeprazol pode aumentar ligeiramente o efeito da varfarina, com risco de elevação do INR.', 'Omeprazole may slightly increase the effect of warfarin, with a risk of INR elevation.', 'O omeprazol inibe o CYP2C19 e pode alterar o metabolismo da varfarina (isómero R).', 'Omeprazole inhibits CYP2C19 and may alter warfarin metabolism (R-isomer).', 'Monitorizar o INR ao iniciar ou suspender o omeprazol.', 'Monitor the INR when starting or stopping omeprazole.', 'Monitorizar INR com maior frequência.', 'Monitor the INR more frequently.', 'Hemorragia por INR supraterapêutico.', 'Bleeding from supratherapeutic INR.', 'DailyMed (FDA) — rótulo aprovado Omeprazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6ea9a6f3-b756-4cdf-b3db-f666a2c17d66 ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Omeprazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6ea9a6f3-b756-4cdf-b3db-f666a2c17d66 ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('omeprazol', 'antiacidos', 'moderate', 'Os antiácidos podem reduzir a absorção do omeprazol se tomados em simultâneo.', 'Antacids may reduce omeprazole absorption when taken at the same time.', 'Alteração do pH e da dissolução das cápsulas gastrorresistentes pelo antiácido.', 'Gastric pH change and altered dissolution of gastro-resistant capsules by the antacid.', 'Separar as tomas (2 horas).', 'Separate administration times (2 hours).', 'Vigiar a resposta à terapêutica antiácida/antiulcerosa.', 'Monitor response to antacid/anti-ulcer therapy.', 'Controlo insuficiente dos sintomas.', 'Insufficient symptom control.', 'DailyMed (FDA) — rótulo aprovado Omeprazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6ea9a6f3-b756-4cdf-b3db-f666a2c17d66 ; rótulo aprovado Antiácidos: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Omeprazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6ea9a6f3-b756-4cdf-b3db-f666a2c17d66 ; approved Antacids label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('antiacidos', 'levotiroxina', 'moderate', 'Os antiácidos (alumínio e magnésio) reduzem a absorção da levotiroxina se tomados em simultâneo.', 'Antacids (aluminium and magnesium) reduce levothyroxine absorption when taken at the same time.', 'Quelação/adsorção da levotiroxina pelos catiões do antiácido.', 'Chelation/adsorption of levothyroxine by antacid cations.', 'Separar as tomas (4 horas) e monitorizar TSH.', 'Separate administration times (4 hours) and monitor TSH.', 'Monitorizar TSH e sintomas de hipotiroidismo.', 'Monitor TSH and hypothyroidism symptoms.', 'Hipotiroidismo descompensado.', 'Decompensated hypothyroidism.', 'DailyMed (FDA) — rótulo aprovado Antiácidos: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f ; rótulo aprovado Levotiroxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Antacids label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e346dc0-69ce-4cc5-bb5d-bfa833e11c1f ; approved Levothyroxine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=55f4c679-86cb-b97f-e063-6294a90ad5ef — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)')
) AS v(slug_a, slug_b, severity, summary_pt, summary_en,
       mechanism_pt, mechanism_en, management_pt, management_en,
       monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
       source_pt, source_en)
JOIN public.drugs a ON a.slug = v.slug_a
JOIN public.drugs b ON b.slug = v.slug_b
ON CONFLICT (drug_a_id, drug_b_id) DO NOTHING;

